CREATE TABLE `reship_orders` (`id` BIGINT NOT NULL AUTO_INCREMENT,`public_id` VARCHAR(36) NOT NULL,`reship_no` VARCHAR(34) NOT NULL,`aftersale_id` BIGINT NOT NULL,`created_by_admin_id` BIGINT NOT NULL,`status` ENUM('WAIT_SHIP','SHIPPED','CANCELLED') NOT NULL DEFAULT 'WAIT_SHIP',`address_snapshot` JSON NOT NULL,`reason` VARCHAR(200) NOT NULL,`cost_amount_cent` INT UNSIGNED NOT NULL DEFAULT 0,`idempotency_key` VARCHAR(128) NOT NULL,`request_hash` CHAR(64) NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,UNIQUE INDEX `reship_orders_public_id_key`(`public_id`),UNIQUE INDEX `reship_orders_reship_no_key`(`reship_no`),UNIQUE INDEX `reship_orders_aftersale_id_key`(`aftersale_id`),UNIQUE INDEX `reship_orders_idempotency_key_key`(`idempotency_key`),INDEX `reship_orders_status_created_at_idx`(`status`,`created_at`),INDEX `reship_orders_created_by_admin_id_idx`(`created_by_admin_id`),PRIMARY KEY(`id`),CONSTRAINT `reship_orders_aftersale_id_fkey` FOREIGN KEY(`aftersale_id`) REFERENCES `aftersales`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `reship_orders_created_by_admin_id_fkey` FOREIGN KEY(`created_by_admin_id`) REFERENCES `admin_users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `reship_items` (`id` BIGINT NOT NULL AUTO_INCREMENT,`reship_order_id` BIGINT NOT NULL,`order_item_id` BIGINT NOT NULL,`batch_id` BIGINT NOT NULL,`quantity` TINYINT UNSIGNED NOT NULL,`unit_cost_cent` INT UNSIGNED NOT NULL,UNIQUE INDEX `reship_items_reship_order_id_order_item_id_batch_id_key`(`reship_order_id`,`order_item_id`,`batch_id`),INDEX `reship_items_order_item_id_idx`(`order_item_id`),INDEX `reship_items_batch_id_idx`(`batch_id`),PRIMARY KEY(`id`),CONSTRAINT `reship_items_reship_order_id_fkey` FOREIGN KEY(`reship_order_id`) REFERENCES `reship_orders`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `reship_items_order_item_id_fkey` FOREIGN KEY(`order_item_id`) REFERENCES `order_items`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `reship_items_batch_id_fkey` FOREIGN KEY(`batch_id`) REFERENCES `inventory_batches`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
